class Solution {
public:
    int minAddToMakeValid(string s) {
        int open = 0, adds = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == '(') open++;
            else if (open > 0) open--;
            else adds++;
        }
        return adds + open;
    }
};
